insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-249', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Metallic character in the set Na, Mg, Al decreases from', '["aluminium to sodium","sodium to aluminium","magnesium to sodium","aluminium to argon"]'::jsonb, 1, 'Across period 3 the atoms become smaller and harder to ionise, so metallic character falls Na > Mg > Al.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'metallic-character') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
