insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-252', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Silicon is classified as a metalloid, sitting on the diagonal staircase of the', '["s-block","p-block","f-block","noble-gas column"]'::jsonb, 1, 'Si lies between the metal Al and the non-metal P and shows intermediate electrical and chemical behaviour.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'metallic-character') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
