insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-253', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Caesium is more metallic than lithium because the valence electron of Cs is', '["closer to the nucleus and harder to lose","farther from the nucleus and more easily lost","a 2s electron","part of a filled p⁶ set"]'::jsonb, 1, 'The 6s electron of Cs is highly shielded, so Cs has a very low IE and extreme metallic character.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'metallic-character') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
