insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-254', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Aluminium is distinctly more metallic than boron, even though both head group 13, because Al is', '["smaller and has a higher ionisation enthalpy","larger and has a much lower ionisation enthalpy","a noble gas","an f-block element"]'::jsonb, 1, 'Two trends reinforce: down the group size rises and IE falls, turning the head (B, a non-metal/metalloid) into a metal (Al).', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'metallic-character') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
